WITH RecursiveTagHierarchy (TagId, ParentTagId, GenerateLevel) AS (
    SELECT t.Id, NULL::INT, 1 FROM Tags t WHERE t.IsModeratorOnly = 0
    UNION ALL
    SELECT t.Id, r.TagId, r.GenerateLevel + 1 
    FROM Tags t
    JOIN RecursiveTagHierarchy r ON t.Id = r.ParentTagId 
    WHERE r.GenerateLevel < 5
),
ComplexUserAggregates AS (
    SELECT
        u.Id,
        u.DisplayName,
        u.Reputation,
        u.CreationDate,
        strlen_trimmed.AboutLength,
